-- Reverse of apply.sql: removes the six profiles (only if they are still the ones written on 2026-10-15). Generated by Build-Sql.py.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
DO $$ DECLARE n int; BEGIN
  DELETE FROM editorial_profiles WHERE publisher_id IN (8980, 8978, 8982, 8983, 8981, 8979) AND classification_date = DATE '2026-10-15';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 6 THEN RAISE EXCEPTION 'deleted %, expected 6 - rolled back', n; END IF;
END $$;
COMMIT;
SELECT 'reversed|' || count(*) || ' profiles left for these publishers' FROM editorial_profiles WHERE publisher_id IN (8980, 8978, 8982, 8983, 8981, 8979);
